-- Só migra uma vez por conta/conjunto; reexecutar não restaura capturas desmarcadas.
create temporary table livingdex_old_marks on commit drop as
select m.* from pokeatlas_private.game_tracker_marks m
where m.game_key in ('sword-shield', 'scarlet-violet', 'legends-za')
and not exists (
  select 1 from pokeatlas_private.livingdex_split_backups b
  where b.account_id = m.account_id and b.game_key = m.game_key
);
insert into pokeatlas_private.livingdex_split_backups(account_id, game_key, pokemon_ids)
select account_id, game_key, array_agg(pokemon_id order by pokemon_id)
from livingdex_old_marks group by account_id, game_key
on conflict do nothing;

insert into pokeatlas_private.game_tracker_marks(account_id, game_key, pokemon_id, created_at)
select m.account_id, s.game_key, m.pokemon_id, m.created_at
from livingdex_old_marks m join livingdex_scopes s
on s.parent_key = m.game_key and s.game_key <> s.parent_key and m.pokemon_id = any(s.pokemon_ids)
on conflict do nothing;

-- Tira do jogo base apenas as marcações copiadas para as DLCs.
delete from pokeatlas_private.game_tracker_marks m
using livingdex_old_marks old, livingdex_scopes s
where m.account_id = old.account_id and m.game_key = old.game_key and m.pokemon_id = old.pokemon_id
and s.game_key = m.game_key and s.game_key = s.parent_key
and not (m.pokemon_id = any(s.pokemon_ids));
commit;
